"""Fetch API request/response types."""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

FetchFormat = Literal["markdown", "html", "json"]


class FetchHighlights(BaseModel):
    """Request query-ranked snippets from each page; markdown format only."""

    # strict: no coercion; forbid: a typo'd key must not silently fall to a default.
    model_config = ConfigDict(strict=True, extra="forbid")

    query: str = Field(..., min_length=1, description="Query used to rank and select snippets")
    max_snippets: int = Field(5, ge=1, le=20, description="Maximum snippets per URL")
    max_characters: int | None = Field(None, ge=1, description="Total character cap across snippets")
    include_full_page_text: bool = Field(False, description="Also populate text; otherwise text is None")


class HighlightSnippet(BaseModel):
    """A single highlighted snippet extracted from a page."""

    text: str = Field(..., description="Verbatim snippet text")
    rank: int = Field(..., description="1-based relevance rank, 1 = most relevant")


class FetchResult(BaseModel):
    """A single successfully fetched URL result."""

    url: str = Field(..., description="The original requested URL")
    final_url: str | None = Field(None, description="The final URL after redirects")
    title: str | None = Field(None, description="Page title")
    description: str | None = Field(None, description="Page meta description")
    language: str | None = Field(None, description="Detected language code")
    author: str | None = Field(None, description="Content author")
    published_date: str | None = Field(None, description="Publication date")
    text: str | None = Field(None, description="Extracted content in the requested format")
    format: FetchFormat = Field(..., description="Output format used")
    links: list[str] = Field(default_factory=list, description="Extracted links")
    image_links: list[str] = Field(default_factory=list, description="Extracted image links")
    latency_ms: float | None = Field(None, description="Fetch latency in milliseconds")
    not_modified: bool | None = Field(
        None,
        description=(
            "True only for a successful 304 returned against the caller-supplied "
            "if_none_match / if_modified_since validators. Omitted (None) when "
            "conditional headers were not used or not requested via "
            "include_etag_and_last_modified."
        ),
    )
    etag: str | None = Field(None, description="Origin ETag validator; omitted when not applicable")
    last_modified: str | None = Field(
        None,
        description="Origin Last-Modified validator; omitted when not applicable",
    )
    highlights: list[HighlightSnippet] | None = Field(
        None, description="Query-ranked snippets; present only when highlights was requested"
    )


class FetchError(BaseModel):
    """A single failed fetch result."""

    url: str = Field(..., description="The URL that failed")
    error: str = Field(..., description="Error message")


class FetchResponse(BaseModel):
    """Response from POST /v1/fetch."""

    results: list[FetchResult] = Field(..., description="Successfully fetched results")
    errors: list[FetchError] = Field(..., description="Failed fetch results")
